   189	/**
   190	 * Validate that given date is in a specified range of years before now.
   191	 */
   192	function getAgeRequirementError(date: string, minimumAge: number, maximumAge: number): string {
   193	    const currentDate = startOfDay(new Date());
   194	    const testDate = parse(date, CONST.DATE.FNS_FORMAT_STRING, currentDate);
   195	
   196	    if (!isValid(testDate)) {
   197	        return Localize.translateLocal('common.error.dateInvalid');
   198	    }
   199	
   200	    const maximalDate = subYears(currentDate, minimumAge);
   201	    const minimalDate = subYears(currentDate, maximumAge);
   202	
   203	    if (isWithinInterval(testDate, {start: minimalDate, end: maximalDate})) {
   204	        return '';
   205	    }
   206	
   207	    if (isSameDay(testDate, maximalDate) || isAfter(testDate, maximalDate)) {
   208	        return Localize.translateLocal('privatePersonalDetails.error.dateShouldBeBefore', {dateString: format(maximalDate, CONST.DATE.FNS_FORMAT_STRING)});
   209	    }
   210	
   211	    return Localize.translateLocal('privatePersonalDetails.error.dateShouldBeAfter', {dateString: format(minimalDate, CONST.DATE.FNS_FORMAT_STRING)});
   212	}
