   317	/**
   318	 * Checks the given number is a valid US Routing Number
   319	 * using ABA routingNumber checksum algorithm: http://www.brainjar.com/js/validation/
   320	 */
   321	function isValidRoutingNumber(routingNumber: string): boolean {
   322	    let n = 0;
   323	    for (let i = 0; i < routingNumber.length; i += 3) {
   324	        n += parseInt(routingNumber.charAt(i), 10) * 3 + parseInt(routingNumber.charAt(i + 1), 10) * 7 + parseInt(routingNumber.charAt(i + 2), 10);
   325	    }
   326	
   327	    // If the resulting sum is an even multiple of ten (but not zero),
   328	    // the ABA routing number is valid.
   329	    if (n !== 0 && n % 10 === 0) {
   330	        return true;
   331	    }
   332	    return false;
   333	}
